export function initCookies(){const e=document.querySelector(".cookies-wrapper"),t=document.querySelector("footer button.cookie-banner"),c=e.querySelector(".cookies-agree button.save"),o=e.querySelector(".cookies-agree button.reject"),n=e.querySelector("input#marketing"),i=e.querySelector("input#statistic");function r(){e.classList.remove("show")}function s(e,t){document.cookie=`marketing_consent=${e}; max-age=15552000; path=/`,document.cookie=`statistic_consent=${t}; max-age=15552000; path=/`}t.addEventListener("click",(function(){e.classList.add("show")})),c.addEventListener("click",(function(){s(n.checked,i.checked),r()})),o.addEventListener("click",(function(){n.checked=!1,i.checked=!1,s(n.checked,i.checked),r()}))}